        instr_dly_q <= instr;
      else
        instr_dly_q <= '0;
      if (|(instr_dly_q.commit_ack & ~instr_dly_q.commit_drop)
          || instr_dly_q.ex_commit_valid) begin
        instr_q <= instr_dly_q;
        csr_q   <= csr;
      end else begin
        instr_q <= '0;
        csr_q   <= '0;
      end
    end else begin
      instr_dly_q <= instr;
      instr_q     <= instr_dly_q;
      csr_q       <= csr;
    end
  end

  always_comb begin
    rvfi_probes_o = '0;

    if ($bits(rvfi_probes_o.instr) == $bits(instr_q)) begin
      rvfi_probes_o.instr = instr_q;
    end

    if ($bits(rvfi_probes_o.csr) == $bits(csr_q)) begin
      rvfi_probes_o.csr = csr_q;
    end

